// Build the notification text.
//
// Nothing here reads a credential. The bot token lives ONLY in the n8n
// credential store (encrypted with N8N_ENCRYPTION_KEY) and is attached by the
// Telegram node below — it never appears in this code, in the workflow JSON, or
// in an execution log.

const now = new Date().toISOString();

const message = [
  '📋 Project Control — daily status',
  '',
  `host: ${$env.HOSTNAME ?? 'project-control'}`,
  `time: ${now}`,
  '',
  'This is an example workflow. Replace this node with real checks',
  'against the Control API once Stage 2 exposes them.',
].join('\n');

return [{ json: { message } }];
